.container {
  /* 魔法咒语开启 🪄 */
  display: flex;

  /* 水平居中，稳如泰山 🧘‍♂️ */
  justify-content: center;

  /* 垂直居中，丝毫不差 🎯 */
  align-items: center;

  /* 甚至还可以加点呼吸空间 😮‍💨 */
  gap: 1rem;
}

.grid-galaxy {
  display: grid;

  /* 响应式黑科技：根据屏幕宽度自动塞下尽可能多的 200px 盒子 📦 */
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));

  /* 完美的缝隙 🧱 */
  gap: 16px;
}
